49- *  whose date falls in it and that counted by the status each had at the end of the period's last day (see
50- *  statusAsOf; a claim added after it does not count), the live rules otherwise applying (a deferred claim does
51- *  not count, nor a claim open now dated within a hold of its person, not bound by a statement), added up (skipping
52- *  n/a); for a closed or soft-closed period, their figure fixed when it was (soft-)closed (0.00 for a person added after). */
53:export function personPeriodDue(
54-  period: Period,
55-  person: Person,
56-  claims: Claim[] | undefined,
57-  rates: Rate[] | undefined,
58-  floor: Dated,
59-  late: Late,
60-): string {
61-  if (period.closed || period.soft) return period.personTotals?.[String(person.id)] ?? '0.00';
62-  const mine = (claims ?? []).filter((c) => {
63-    if (c.personId !== person.id || c.date < period.from || period.to < c.date) return false;
64-    const status = statusAsOf(c, period.to);
65-    return status !== undefined && counts({ ...c, status }) && !(isOpen(c) && !bound(c) && heldOn(person, c.date));
66-  });
67-  return sum(mine.map((c) => claimDue(c, rateFor(rates, gradeOn(person, c.date), c.date), floor, late)));
68-}
