70:/** A period's due-total: the people's due-totals for it (see personPeriodDue) added up. */
71-export function periodDue(
72-  period: Period,
73-  claims: Claim[] | undefined,
74-  people: Person[] | undefined,
75-  rates: Rate[] | undefined,
76-  floor: Dated,
77-  late: Late,
78-): string {
79:  return sum((people ?? []).map((person) => personPeriodDue(period, person, claims, rates, floor, late)));
80-}
12:export type Period = {
13-  id: number;
14-  sheetId: string;
15-  name: string;
16-  from: string;
17-  to: string;
18-  closed: boolean;
19-  /** Soft-closed (not closed): its figures are fixed as for a close, but claims dated inside it can still change. */
20-  soft: boolean;
21-  closedTotal: string | null;
22-  /** Closed or soft-closed, each person's due-total for the period fixed when it was closed, by person id. */
23-  personTotals: Record<string, string>;
24-};

